//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_selected_phase(value: *mut Drone_Lifecycle_Governor::Lifecycle_Phase) -> bool;
  fn put_lifecycle_enablement(value: *mut Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool;
}

pub fn unsafe_get_selected_phase() -> Drone_Lifecycle_Governor::Lifecycle_Phase
{
  unsafe {
    let value: *mut Drone_Lifecycle_Governor::Lifecycle_Phase = &mut Drone_Lifecycle_Governor::Lifecycle_Phase::default();
    get_selected_phase(value);
    return *value;
  }
}

pub fn unsafe_put_lifecycle_enablement(value: &Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  unsafe {
    return put_lifecycle_enablement(value as *const Drone_Lifecycle_Governor::Lifecycle_Enablement as *mut Drone_Lifecycle_Governor::Lifecycle_Enablement);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_selected_phase: Mutex<Option<Drone_Lifecycle_Governor::Lifecycle_Phase>> = Mutex::new(None);
  pub static ref OUT_lifecycle_enablement: Mutex<Option<Drone_Lifecycle_Governor::Lifecycle_Enablement>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_selected_phase.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_lifecycle_enablement.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_selected_phase(value: *mut Drone_Lifecycle_Governor::Lifecycle_Phase) -> bool
{
  unsafe {
    let guard = IN_selected_phase.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_lifecycle_enablement(value: *mut Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  unsafe {
    *OUT_lifecycle_enablement.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
